#[derive(Template)]                    // stage 1 + stage 2: page and HTML renderer
#[template(path = "invoice.html")]
struct InvoiceHtml<'a> { customer: &'a str, total: &'a str }

#[derive(Serialize)]                   // same page, JSON channel
struct InvoiceJson<'a> { customer: &'a str, total: &'a str }

let html = InvoiceHtml { customer, total }.render()?;
let json = serde_json::to_string(&InvoiceJson { customer, total })?;
